local p=Game.GetScriptableSystemsContainer():Get("PreventionSystem"); local s=Game.GetPreventionSpawnSystem(); local v=Game.GetPlayer(); local function r(n,f) local ok,x=pcall(f); print(n.."="..(ok and x~=nil and tostring(x) or "Unknown")); end; r("enabled",function() return p:IsSystemEnabled() end); r("locked",function() return p:IsSystemLocked() end); r("canReact",function() return p:CanPreventionReactToInput() end); r("Dogtown",function() return p:GetCurrentDistrict():IsDogTown() end); r("freeArea",function() return s:IsPointInPreventionFreeArea(v:GetWorldPosition()) end); r("heat",function() return p:GetHeatStageAsInt() end)
